//! ⚙️ Handwritten gains, HVAC, airflow, electrical and reporting entities.
use super::*;
const PEOPLE:&[FloatColumn]=&[FloatColumn::Binary64(7),FloatColumn::Binary64(8),FloatColumn::Binary64(9),FloatColumn::Binary64(10)];
const LIGHTING:&[FloatColumn]=&[FloatColumn::Binary64(6),FloatColumn::Binary64(7),FloatColumn::Binary64(8),FloatColumn::Binary64(9)];
const EQUIPMENT:&[FloatColumn]=&[FloatColumn::Binary64(6),FloatColumn::Binary64(7),FloatColumn::Binary64(8)];
const THERMOSTAT:&[FloatColumn]=&[FloatColumn::Binary64(7),FloatColumn::Binary64(8)];
const RESET:&[FloatColumn]=&[FloatColumn::Binary64(1),FloatColumn::Binary64(2),FloatColumn::Binary64(3),FloatColumn::Binary64(4)];
const IDEAL:&[FloatColumn]=&[FloatColumn::Binary64(5),FloatColumn::Binary64(6),FloatColumn::Binary64(7),FloatColumn::Binary64(8),FloatColumn::Binary64(9),FloatColumn::Binary64(10)];
const ZONE_EQUIPMENT:&[FloatColumn]=&[FloatColumn::Binary64(7),FloatColumn::Binary64(8)];
const AIR_LOOP:&[FloatColumn]=&[FloatColumn::Binary64(7)];
const PLANT:&[FloatColumn]=&[FloatColumn::Binary64(6),FloatColumn::Binary64(7),FloatColumn::Binary64(8)];
const OUTDOOR:&[FloatColumn]=&[FloatColumn::Binary64(5)];
const INFILTRATION:&[FloatColumn]=&[FloatColumn::Binary64(7),FloatColumn::Binary64(8),FloatColumn::Binary64(9),FloatColumn::Binary64(10),FloatColumn::Binary64(11),FloatColumn::Binary64(12),FloatColumn::Binary64(13),FloatColumn::Binary64(14),FloatColumn::Binary64(15)];
const PV:&[FloatColumn]=&[FloatColumn::Binary64(4),FloatColumn::Binary64(5),FloatColumn::Binary64(6),FloatColumn::Binary64(7),FloatColumn::Binary64(8),FloatColumn::Binary64(9)];
const BATTERY:&[FloatColumn]=&[FloatColumn::Binary64(4),FloatColumn::Binary64(5),FloatColumn::Binary64(6),FloatColumn::Binary64(7)];
const SHW:&[FloatColumn]=&[FloatColumn::Binary64(4),FloatColumn::Binary64(5),FloatColumn::Binary64(6)];
const SOLAR:&[FloatColumn]=&[FloatColumn::Binary64(4),FloatColumn::Binary64(5),FloatColumn::Binary64(6),FloatColumn::Binary64(7),FloatColumn::Binary64(8)];
const REFRIGERATION:&[FloatColumn]=&[FloatColumn::Binary64(5)];
const FAULT:&[FloatColumn]=&[FloatColumn::Binary64(6)];
const DAYLIGHT:&[FloatColumn]=&[FloatColumn::Binary64(5),FloatColumn::Binary64(6),FloatColumn::Binary64(7)];
fn optional_float(v:Option<f64>)->Cell<'static>{v.map_or(Cell::Null,Cell::Real)}
fn read_optional_float(v:FloatRow<'_>,n:usize)->Result<Option<f64>,ValueError>{if v.is_null(n)?{Ok(None)}else{v.real(n).map(Some)}}
fn zone_equipment(v:&ZoneEquipmentType)->&'static str{match v{ZoneEquipmentType::Baseboard=>"Baseboard",ZoneEquipmentType::Radiant=>"Radiant",ZoneEquipmentType::FanCoil=>"FanCoil",ZoneEquipmentType::Ptac=>"Ptac",ZoneEquipmentType::VrfTerminal=>"VrfTerminal",ZoneEquipmentType::Erv=>"Erv",ZoneEquipmentType::UnitHeater=>"UnitHeater",ZoneEquipmentType::WaterToAirHp=>"WaterToAirHp"}}
fn fault(v:FaultType)->&'static str{match v{FaultType::SensorBias=>"SensorBias",FaultType::CoilFouling=>"CoilFouling",FaultType::DamperStuck=>"DamperStuck",FaultType::ChillerFouling=>"ChillerFouling",FaultType::BoilerEfficiencyDegradation=>"BoilerEfficiencyDegradation"}}
fn frequency(v:OutputReportFrequency)->&'static str{match v{OutputReportFrequency::Timestep=>"Timestep",OutputReportFrequency::Hourly=>"Hourly",OutputReportFrequency::Daily=>"Daily",OutputReportFrequency::Monthly=>"Monthly",OutputReportFrequency::RunPeriod=>"RunPeriod"}}
fn room_air(v:RoomAirModelType)->&'static str{match v{RoomAirModelType::WellMixed=>"WellMixed",RoomAirModelType::OneNodeDisplacement=>"OneNodeDisplacement",RoomAirModelType::TwoNodeBuoyancy=>"TwoNodeBuoyancy",RoomAirModelType::UnderFloorAirDistribution=>"UnderFloorAirDistribution"}}
fn scalar<T:semio_framework_dsl_record::DslField>(v:FloatRow<'_>,n:usize,labels:&[&str])->Result<T,ValueError>{let label=v.text(n)?;let ordinal=labels.iter().position(|name|*name==label).ok_or_else(||invalid("Energy enum label differs"))?;T::from_value(&semio_framework_dsl_record::FieldValue::Enum(u32::try_from(ordinal).map_err(|_|semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"Energy enum ordinal overflow"))?)).map_err(invalid)}
pub(super)fn project(m:&Model,p:&mut RowWriter<'_,'_>)->Result<(),ValueError>{
 for(n,v)in m.people.iter().enumerate(){emit(p,"energy_people",n,&[i(v.id.0),i(v.zone_id.0),i(v.schedule_id.0),i(v.activity_schedule_id.0),Cell::Real(v.people_per_area),Cell::Real(v.sensible_fraction),Cell::Real(v.latent_fraction),Cell::Real(v.radiant_fraction)],PEOPLE)?;}
 for(n,v)in m.lighting.iter().enumerate(){emit(p,"energy_lighting",n,&[i(v.id.0),i(v.zone_id.0),i(v.schedule_id.0),Cell::Real(v.watts_per_area),Cell::Real(v.radiant_fraction),Cell::Real(v.visible_fraction),Cell::Real(v.return_air_fraction)],LIGHTING)?;}
 for(n,v)in m.equipment.iter().enumerate(){emit(p,"energy_equipment",n,&[i(v.id.0),i(v.zone_id.0),i(v.schedule_id.0),Cell::Real(v.watts_per_area),Cell::Real(v.radiant_fraction),Cell::Real(v.latent_fraction)],EQUIPMENT)?;}
 for(n,v)in m.thermostats.iter().enumerate(){emit(p,"energy_thermostat",n,&[i(v.id.0),i(v.zone_id.0),i(v.heating_setpoint_schedule_id.0),i(v.cooling_setpoint_schedule_id.0),Cell::Real(v.heating_throttle_range_k),Cell::Real(v.cooling_throttle_range_k)],THERMOSTAT)?;}
 for(n,v)in m.humidistats.iter().enumerate(){emit(p,"energy_humidistat",n,&[i(v.id.0),i(v.zone_id.0),i(v.humidifying_setpoint_schedule_id.0),i(v.dehumidifying_setpoint_schedule_id.0),Cell::Real(v.humidifying_throttle_range),Cell::Real(v.dehumidifying_throttle_range)],THERMOSTAT)?;}
 for(n,v)in m.setpoint_managers.iter().enumerate(){let kind=match &v.kind{SetpointManagerKind::Scheduled=>"Scheduled",SetpointManagerKind::OutdoorAirReset{..}=>"OutdoorAirReset",SetpointManagerKind::WarmestZone=>"WarmestZone",SetpointManagerKind::ColdestZone=>"ColdestZone"};let id=emit(p,"energy_setpoint_manager",n,&[i(v.id.0),Cell::Text(&v.name),Cell::Text(kind),optional_schedule(v.schedule_id)],&[])?;if let SetpointManagerKind::OutdoorAirReset{low_outdoor_c,high_outdoor_c,low_setpoint_c,high_setpoint_c}=v.kind{p.insert_key_float("energy_setpoint_outdoor_reset",id,&[Cell::Real(low_outdoor_c),Cell::Real(high_outdoor_c),Cell::Real(low_setpoint_c),Cell::Real(high_setpoint_c)],RESET)?;}}
 for(n,v)in m.ideal_loads.iter().enumerate(){emit(p,"energy_ideal_loads",n,&[i(v.id.0),i(v.zone_id.0),Cell::Real(v.max_heating_supply_air_temp_c),Cell::Real(v.min_cooling_supply_air_temp_c),optional_float(v.max_heating_capacity_w),optional_float(v.max_cooling_capacity_w),Cell::Real(v.outdoor_air_per_person_m3_s),Cell::Real(v.outdoor_air_per_area_m3_s_m2)],IDEAL)?;}
 for(n,v)in m.zone_equipment.iter().enumerate(){emit(p,"energy_zone_equipment",n,&[i(v.id.0),i(v.zone_id.0),Cell::Text(zone_equipment(&v.equipment_type)),i(u32::from(v.priority)),Cell::Real(v.heating_capacity_w),Cell::Real(v.cooling_capacity_w)],ZONE_EQUIPMENT)?;}
 for(n,v)in m.air_loops.iter().enumerate(){let id=emit(p,"energy_air_loop",n,&[i(v.id.0),Cell::Text(&v.name),i(v.supply_node_id),i(v.return_node_id),Cell::Real(v.design_supply_air_flow_m3_s)],AIR_LOOP)?;ids(p,"energy_air_loop_terminal",id,&v.terminal_zone_ids)?;}
 for(n,v)in m.plant_loops.iter().enumerate(){let kind=match v.loop_type{PlantLoopType::Heating=>"Heating",PlantLoopType::Cooling=>"Cooling",PlantLoopType::Condenser=>"Condenser"};let id=emit(p,"energy_plant_loop",n,&[i(v.id.0),Cell::Text(&v.name),Cell::Text(kind),Cell::Real(v.supply_temperature_c),Cell::Real(v.return_temperature_c),Cell::Real(v.design_flow_kg_s)],PLANT)?;ids(p,"energy_plant_loop_equipment",id,&v.equipment_ids)?;}
 for(n,v)in m.outdoor_air_systems.iter().enumerate(){emit(p,"energy_outdoor_air_system",n,&[i(v.id.0),i(v.air_loop_id.0),Cell::Real(v.min_oa_flow_m3_s),b(v.economizer_enabled)],OUTDOOR)?;}
 for(n,v)in m.infiltrations.iter().enumerate(){let method=match v.method{crate::air_exchange::InfiltrationMethod::ScheduledAch=>"ScheduledAch",crate::air_exchange::InfiltrationMethod::PerExteriorArea=>"PerExteriorArea",crate::air_exchange::InfiltrationMethod::EffectiveLeakageArea=>"EffectiveLeakageArea",crate::air_exchange::InfiltrationMethod::WindAndStack=>"WindAndStack"};emit(p,"energy_infiltration",n,&[i(v.id.0),i(v.zone_id.0),i(v.schedule_id.0),Cell::Text(method),Cell::Real(v.design_flow_ach),Cell::Real(v.flow_per_exterior_area_m3_s_m2),Cell::Real(v.effective_leakage_area_m2),Cell::Real(v.discharge_coefficient),Cell::Real(v.stack_height_m),Cell::Real(v.constant_term_coefficient),Cell::Real(v.temperature_term_coefficient),Cell::Real(v.velocity_term_coefficient),Cell::Real(v.velocity_squared_term_coefficient)],INFILTRATION)?;}
 for(n,v)in m.mechanical_ventilations.iter().enumerate(){emit(p,"energy_mechanical_ventilation",n,&[i(v.id.0),i(v.zone_id.0),i(v.schedule_id.0),Cell::Real(v.design_flow_m3_s),Cell::Real(v.fan_total_efficiency),Cell::Real(v.fan_delta_pressure_pa)],EQUIPMENT)?;}
 if let Some(v)=&m.airflow_network{p.insert_key("energy_airflow_network",1,&[i(v.outdoor_node_id)])?;for(n,(zone,node))in v.zone_node_ids.iter().enumerate(){edge(p,"energy_airflow_zone_node",1,n,&[i(zone.0),i(*node)],&[])?;}for(n,link)in v.link_ids.iter().enumerate(){edge(p,"energy_airflow_link",1,n,&[i(*link)],&[])?;}}
 for(n,v)in m.electrical_load_centers.iter().enumerate(){let id=emit(p,"energy_electrical_load_center",n,&[i(v.id.0),Cell::Text(&v.name)],&[])?;ids(p,"energy_electrical_generator",id,&v.generator_ids)?;ids(p,"energy_electrical_pv",id,&v.pv_ids)?;ids(p,"energy_electrical_battery",id,&v.battery_ids)?;}
 for(n,v)in m.pv_systems.iter().enumerate(){emit(p,"energy_pv_system",n,&[i(v.id.0),Cell::Real(v.dc_capacity_w),Cell::Real(v.area_m2),Cell::Real(v.tilt_deg),Cell::Real(v.azimuth_deg),Cell::Real(v.module_efficiency),Cell::Real(v.inverter_efficiency)],PV)?;}
 for(n,v)in m.battery_storage.iter().enumerate(){emit(p,"energy_battery",n,&[i(v.id.0),Cell::Real(v.capacity_kwh),Cell::Real(v.max_charge_w),Cell::Real(v.max_discharge_w),Cell::Real(v.round_trip_efficiency)],BATTERY)?;}
 for(n,v)in m.shw_systems.iter().enumerate(){emit(p,"energy_shw_system",n,&[i(v.id.0),Cell::Real(v.heater_capacity_w),Cell::Real(v.storage_volume_m3),Cell::Real(v.setpoint_c),i(v.schedule_id.0)],SHW)?;}
 for(n,v)in m.solar_thermal_systems.iter().enumerate(){emit(p,"energy_solar_thermal",n,&[i(v.id.0),Cell::Real(v.collector_area_m2),Cell::Real(v.efficiency),Cell::Real(v.storage_volume_m3),Cell::Real(v.tilt_deg),Cell::Real(v.azimuth_deg)],SOLAR)?;}
 for(n,v)in m.refrigeration_systems.iter().enumerate(){emit(p,"energy_refrigeration",n,&[i(v.id.0),i(v.case_count),Cell::Real(v.design_load_w),i(v.defrost_schedule_id.0)],REFRIGERATION)?;}
 for(n,v)in m.water_systems.iter().enumerate(){emit(p,"energy_water_system",n,&[i(v.id.0),i(v.fixture_count),Cell::Real(v.peak_flow_l_s),i(v.schedule_id.0)],REFRIGERATION)?;}
 for(n,v)in m.faults.iter().enumerate(){emit(p,"energy_fault",n,&[i(v.id.0),i(v.target_equipment_id.0),Cell::Text(fault(v.fault_type)),Cell::Real(v.severity),i(v.start_schedule_id.0)],FAULT)?;}
 for(n,v)in m.output_variables.iter().enumerate(){emit(p,"energy_output_variable",n,&[Cell::Text(&v.name),Cell::Text(&v.key),Cell::Text(frequency(v.reporting_frequency))],&[])?;}
 for(n,v)in m.sizing_objects.iter().enumerate(){let kind=match v.sizing_type{SizingType::Heating=>"Heating",SizingType::Cooling=>"Cooling",SizingType::OutdoorAir=>"OutdoorAir"};let day=match v.design_day_type{DesignDayType::Heating=>"Heating",DesignDayType::Cooling=>"Cooling"};emit(p,"energy_sizing_object",n,&[i(v.id.0),i(v.zone_id.0),Cell::Text(kind),Cell::Text(day)],&[])?;}
 for(n,v)in m.daylight_zones.iter().enumerate(){emit(p,"energy_daylight_zone",n,&[i(v.id.0),i(v.zone_id.0),Cell::Real(v.illuminance_target_lux),Cell::Real(v.glare_limit),Cell::Real(v.window_transmittance)],DAYLIGHT)?;}
 for(n,v)in m.room_air_models.iter().enumerate(){emit(p,"energy_room_air_model",n,&[i(v.zone_id.0),Cell::Text(room_air(v.model))],&[])?;}Ok(())
}
pub(super)fn reconstruct(m:&mut Model,r:&mut Reader<'_,'_,'_>)->Result<(),ValueError>{
 for v in r.rows("energy_people",1,11,PEOPLE)?{m.people.push(PeopleGain{id:entity(v,3)?,zone_id:entity(v,4)?,schedule_id:schedule(v,5)?,activity_schedule_id:schedule(v,6)?,people_per_area:v.real(7)?,sensible_fraction:v.real(8)?,latent_fraction:v.real(9)?,radiant_fraction:v.real(10)?});}
 for v in r.rows("energy_lighting",1,10,LIGHTING)?{m.lighting.push(LightingGain{id:entity(v,3)?,zone_id:entity(v,4)?,schedule_id:schedule(v,5)?,watts_per_area:v.real(6)?,radiant_fraction:v.real(7)?,visible_fraction:v.real(8)?,return_air_fraction:v.real(9)?});}
 for v in r.rows("energy_equipment",1,9,EQUIPMENT)?{m.equipment.push(EquipmentGain{id:entity(v,3)?,zone_id:entity(v,4)?,schedule_id:schedule(v,5)?,watts_per_area:v.real(6)?,radiant_fraction:v.real(7)?,latent_fraction:v.real(8)?});}
 for v in r.rows("energy_thermostat",1,9,THERMOSTAT)?{m.thermostats.push(Thermostat{id:entity(v,3)?,zone_id:entity(v,4)?,heating_setpoint_schedule_id:schedule(v,5)?,cooling_setpoint_schedule_id:schedule(v,6)?,heating_throttle_range_k:v.real(7)?,cooling_throttle_range_k:v.real(8)?});}
 for v in r.rows("energy_humidistat",1,9,THERMOSTAT)?{m.humidistats.push(Humidistat{id:entity(v,3)?,zone_id:entity(v,4)?,humidifying_setpoint_schedule_id:schedule(v,5)?,dehumidifying_setpoint_schedule_id:schedule(v,6)?,humidifying_throttle_range:v.real(7)?,dehumidifying_throttle_range:v.real(8)?});}
 for v in r.rows("energy_setpoint_manager",1,7,&[])?{let reset=r.optional("energy_setpoint_outdoor_reset",v.rowid,5,RESET)?;let kind=match(v.text(5)?,reset){("Scheduled",None)=>SetpointManagerKind::Scheduled,("WarmestZone",None)=>SetpointManagerKind::WarmestZone,("ColdestZone",None)=>SetpointManagerKind::ColdestZone,("OutdoorAirReset",Some(row))=>SetpointManagerKind::OutdoorAirReset{low_outdoor_c:row.real(1)?,high_outdoor_c:row.real(2)?,low_setpoint_c:row.real(3)?,high_setpoint_c:row.real(4)?},_=>return Err(invalid("Energy setpoint manager variant presence differs"))};m.setpoint_managers.push(SetpointManager{id:entity(v,3)?,name:r.text(v,4)?,kind,schedule_id:optional_schedule_value(v,6)?});}
 for v in r.rows("energy_ideal_loads",1,11,IDEAL)?{m.ideal_loads.push(IdealLoadsSystem{id:entity(v,3)?,zone_id:entity(v,4)?,max_heating_supply_air_temp_c:v.real(5)?,min_cooling_supply_air_temp_c:v.real(6)?,max_heating_capacity_w:read_optional_float(v,7)?,max_cooling_capacity_w:read_optional_float(v,8)?,outdoor_air_per_person_m3_s:v.real(9)?,outdoor_air_per_area_m3_s_m2:v.real(10)?});}
 for v in r.rows("energy_zone_equipment",1,9,ZONE_EQUIPMENT)?{m.zone_equipment.push(ZoneEquipmentAssignment{id:entity(v,3)?,zone_id:entity(v,4)?,equipment_type:scalar(v,5,&["Baseboard","Radiant","FanCoil","Ptac","VrfTerminal","Erv","UnitHeater","WaterToAirHp"])?,priority:u8::try_from(u32_value(v,6)?).map_err(|_|invalid("Energy equipment priority exceeds unsigned8"))?,heating_capacity_w:v.real(7)?,cooling_capacity_w:v.real(8)?});}
 for v in r.rows("energy_air_loop",1,8,AIR_LOOP)?{m.air_loops.push(ModelAirLoop{id:entity(v,3)?,name:r.text(v,4)?,supply_node_id:u32_value(v,5)?,return_node_id:u32_value(v,6)?,design_supply_air_flow_m3_s:v.real(7)?,terminal_zone_ids:read_ids(r,"energy_air_loop_terminal",v.rowid)?});}
 for v in r.rows("energy_plant_loop",1,9,PLANT)?{m.plant_loops.push(PlantLoopConfig{id:entity(v,3)?,name:r.text(v,4)?,loop_type:scalar(v,5,&["Heating","Cooling","Condenser"])?,supply_temperature_c:v.real(6)?,return_temperature_c:v.real(7)?,design_flow_kg_s:v.real(8)?,equipment_ids:read_ids(r,"energy_plant_loop_equipment",v.rowid)?});}
 for v in r.rows("energy_outdoor_air_system",1,7,OUTDOOR)?{m.outdoor_air_systems.push(OutdoorAirSystem{id:entity(v,3)?,air_loop_id:entity(v,4)?,min_oa_flow_m3_s:v.real(5)?,economizer_enabled:boolean(v,6)?});}
 for v in r.rows("energy_infiltration",1,16,INFILTRATION)?{m.infiltrations.push(Infiltration{id:entity(v,3)?,zone_id:entity(v,4)?,schedule_id:schedule(v,5)?,method:scalar(v,6,&["ScheduledAch","PerExteriorArea","EffectiveLeakageArea","WindAndStack"])?,design_flow_ach:v.real(7)?,flow_per_exterior_area_m3_s_m2:v.real(8)?,effective_leakage_area_m2:v.real(9)?,discharge_coefficient:v.real(10)?,stack_height_m:v.real(11)?,constant_term_coefficient:v.real(12)?,temperature_term_coefficient:v.real(13)?,velocity_term_coefficient:v.real(14)?,velocity_squared_term_coefficient:v.real(15)?});}
 for v in r.rows("energy_mechanical_ventilation",1,9,EQUIPMENT)?{m.mechanical_ventilations.push(MechanicalVentilation{id:entity(v,3)?,zone_id:entity(v,4)?,schedule_id:schedule(v,5)?,design_flow_m3_s:v.real(6)?,fan_total_efficiency:v.real(7)?,fan_delta_pressure_pa:v.real(8)?});}
 if let Some(v)=r.one("energy_airflow_network",2,&[],false)?{let mut zone_node_ids=Vec::new();for node in r.rows("energy_airflow_zone_node",1,5,&[])?{zone_node_ids.push((entity(node,3)?,u32_value(node,4)?));}let mut link_ids=Vec::new();for link in r.rows("energy_airflow_link",1,4,&[])?{link_ids.push(u32_value(link,3)?);}m.airflow_network=Some(AirflowNetworkDefinition{outdoor_node_id:u32_value(v,1)?,zone_node_ids,link_ids});}
 for v in r.rows("energy_electrical_load_center",1,5,&[])?{m.electrical_load_centers.push(ElectricalLoadCenter{id:entity(v,3)?,name:r.text(v,4)?,generator_ids:read_ids(r,"energy_electrical_generator",v.rowid)?,pv_ids:read_ids(r,"energy_electrical_pv",v.rowid)?,battery_ids:read_ids(r,"energy_electrical_battery",v.rowid)?});}
 for v in r.rows("energy_pv_system",1,10,PV)?{m.pv_systems.push(PvSystemAssignment{id:entity(v,3)?,dc_capacity_w:v.real(4)?,area_m2:v.real(5)?,tilt_deg:v.real(6)?,azimuth_deg:v.real(7)?,module_efficiency:v.real(8)?,inverter_efficiency:v.real(9)?});}
 for v in r.rows("energy_battery",1,8,BATTERY)?{m.battery_storage.push(BatteryAssignment{id:entity(v,3)?,capacity_kwh:v.real(4)?,max_charge_w:v.real(5)?,max_discharge_w:v.real(6)?,round_trip_efficiency:v.real(7)?});}
 for v in r.rows("energy_shw_system",1,8,SHW)?{m.shw_systems.push(ShwSystemConfig{id:entity(v,3)?,heater_capacity_w:v.real(4)?,storage_volume_m3:v.real(5)?,setpoint_c:v.real(6)?,schedule_id:schedule(v,7)?});}
 for v in r.rows("energy_solar_thermal",1,9,SOLAR)?{m.solar_thermal_systems.push(SolarThermalConfig{id:entity(v,3)?,collector_area_m2:v.real(4)?,efficiency:v.real(5)?,storage_volume_m3:v.real(6)?,tilt_deg:v.real(7)?,azimuth_deg:v.real(8)?});}
 for v in r.rows("energy_refrigeration",1,7,REFRIGERATION)?{m.refrigeration_systems.push(RefrigerationConfig{id:entity(v,3)?,case_count:u32_value(v,4)?,design_load_w:v.real(5)?,defrost_schedule_id:schedule(v,6)?});}
 for v in r.rows("energy_water_system",1,7,REFRIGERATION)?{m.water_systems.push(WaterSystemConfig{id:entity(v,3)?,fixture_count:u32_value(v,4)?,peak_flow_l_s:v.real(5)?,schedule_id:schedule(v,6)?});}
 for v in r.rows("energy_fault",1,8,FAULT)?{m.faults.push(FaultDefinition{id:entity(v,3)?,target_equipment_id:entity(v,4)?,fault_type:scalar(v,5,&["SensorBias","CoilFouling","DamperStuck","ChillerFouling","BoilerEfficiencyDegradation"])?,severity:v.real(6)?,start_schedule_id:schedule(v,7)?});}
 for v in r.rows("energy_output_variable",1,6,&[])?{m.output_variables.push(OutputVariableSpec{name:r.text(v,3)?,key:r.text(v,4)?,reporting_frequency:scalar(v,5,&["Timestep","Hourly","Daily","Monthly","RunPeriod"])?});}
 for v in r.rows("energy_sizing_object",1,7,&[])?{m.sizing_objects.push(SizingObject{id:entity(v,3)?,zone_id:entity(v,4)?,sizing_type:scalar(v,5,&["Heating","Cooling","OutdoorAir"])?,design_day_type:scalar(v,6,&["Heating","Cooling"])?});}
 for v in r.rows("energy_daylight_zone",1,8,DAYLIGHT)?{m.daylight_zones.push(DaylightZoneConfig{id:entity(v,3)?,zone_id:entity(v,4)?,illuminance_target_lux:v.real(5)?,glare_limit:v.real(6)?,window_transmittance:v.real(7)?});}
 for v in r.rows("energy_room_air_model",1,5,&[])?{m.room_air_models.push(RoomAirModelAssignment{zone_id:entity(v,3)?,model:scalar(v,4,&["WellMixed","OneNodeDisplacement","TwoNodeBuoyancy","UnderFloorAirDistribution"])?});}Ok(())
}
